/// <summary>
/// A secret passed to the run operation, for example an endpoint client secret.
/// </summary>
[DataContractAttribute]
public final class BDRServiceSecret
{
    private BDRSecretName name;
    private str secretValue;
}

Method.Source:
[DataMemberAttribute('Name')]
public BDRSecretName parmName(BDRSecretName _name = name)
{
    name = _name;
    return name;
}

[DataMemberAttribute('Value')]
public str parmValue(str _value = secretValue)
{
    secretValue = _value;
    return secretValue;
}
